(989853,34,19,10,4,'in wicked pride, thinks:'),
(989854,34,19,10,5,'Never a season that they do not prosper;'),
(989855,34,19,10,6,'Each says in their heart,'),
(989856,34,19,10,7,'Their mouths are full of deceit and oppression:'),
(989857,34,19,10,8,'Lying in secret in some village ambush,'),
(989858,34,19,10,9,'Like a lion that lurks in a secret lair'),
(989859,34,19,10,10,'Their victims are crushed,'),
(989860,34,19,10,11,'The wicked say in their hearts'),
(989861,34,19,10,12,'Arise,'),
(989862,34,19,10,13,'Why do the wicked treat God with contempt,'),
(989863,34,19,10,14,'You have seen the trouble and sorrow;'),
(989864,34,19,10,15,'Break the arm of the wicked and evil:'),
